import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import OpenAI from 'openai';

@Injectable()
export class OpenAIService {
  private apiKeys: string[] = [];
  private currentKeyIndex = 0;
  private clients: OpenAI[] = [];
  private readonly logger = new Logger(OpenAIService.name);

  constructor(private configService: ConfigService) {
    // Load all available OpenAI keys
    const keys = [
      this.configService.get<string>('OPENAI_API_KEY'),
      this.configService.get<string>('OPENAI_API_KEY2'),
      this.configService.get<string>('OPENAI_API_KEY3'),
      this.configService.get<string>('OPENAI_API_KEY4'),
      this.configService.get<string>('OPENAI_API_KEY5'),
    ].filter((k) => !!k) as string[];

    if (keys.length === 0) {
      this.logger.warn('No OPENAI_API_KEYs found in environment variables');
      this.apiKeys = ['dummy-key'];
    } else {
      this.apiKeys = keys;
      this.logger.log(
        `Initialized with ${this.apiKeys.length} OpenAI API keys.`,
      );
    }

    this.clients = this.apiKeys.map((key) => new OpenAI({ apiKey: key }));
  }

  async generateResponse(
    systemPrompt: string,
    userPrompt: string,
  ): Promise<string> {
    let attempts = 0;
    const maxAttempts = this.apiKeys.length;

    while (attempts < maxAttempts) {
      const client = this.clients[this.currentKeyIndex];
      try {
        const completion = await client.chat.completions.create({
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt },
          ],
          model: 'gpt-4o-mini',
        });
        const content =
          completion.choices[0].message.content || 'AI Service Unavailable';
        this.logger.debug(`AI Response: ${content}`);
        return content;
      } catch (error: any) {
        attempts++;
        this.logger.error(
          `Error with OpenAI Key #${this.currentKeyIndex + 1}: ${error.message}`,
        );

        // If rate limit (429), server error (5xx), OR auth error (401/403), switch key and retry
        if (
          error.status === 429 ||
          error.status >= 500 ||
          error.status === 401 ||
          error.status === 403
        ) {
          this.currentKeyIndex =
            (this.currentKeyIndex + 1) % this.apiKeys.length;
          this.logger.warn(
            `Switching to OpenAI API Key #${this.currentKeyIndex + 1} (Attempt ${attempts + 1}/${maxAttempts}) due to ${error.status}`,
          );
          continue;
        }

        // For other errors, rethrow to be caught by specific handlers
        throw error;
      }
    }

    throw new Error(
      'AI Service Unavailable after multiple retries across all keys',
    );
  }

  async parseResume(resumeText: string): Promise<any> {
    const systemPrompt = `You are an expert HR assistant. Extract the following details from the resume text in JSON format:
    - skills (array of strings)
    - experienceYears (number)
    - keyProjects (array of strings)
    - education (array of strings)
    If a field is not found, return null or empty array. Output ONLY valid JSON.`;

    const response = await this.generateResponse(systemPrompt, resumeText);
    try {
      // Simple cleanup for potential markdown formatting in response
      const cleanJson = response
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      return JSON.parse(cleanJson);
    } catch (e) {
      this.logger.error('Failed to parse AI response as JSON', e);
      return { error: 'Failed to parse resume' };
    }
  }

  async evaluateResume(
    resumeText: string,
    jobDescription: string,
  ): Promise<any> {
    const systemPrompt = `You are an expert technical recruiter.
Compare the following resume with the job description.
Score from 0 to 100 based on fit.
Be objective but fair. For students or early-career candidates, look for relevant coursework, projects, and potential.
If the resume is extremely brief (e.g., only a name), provide low but realistic scores if any keywords match.
Return JSON only in this format:
{
  "skillMatchScore": number,
  "experienceMatch": number,
  "relevanceScore": number,
  "overallScore": number,
  "strengths": string[],
  "weaknesses": string[]
}`;

    const userPrompt = `Job Description:\n${jobDescription}\n\nResume:\n${resumeText}`;
    const response = await this.generateResponse(systemPrompt, userPrompt);
    try {
      const cleanJson = response
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      return JSON.parse(cleanJson);
    } catch (e) {
      this.logger.error('Failed to parse resume evaluation response', e);
      throw new Error('Failed to parse AI response for resume evaluation');
    }
  }

  async generateInterviewQuestion(
    jobDescription: string,
    contextOrTopic: string,
  ): Promise<string> {
    let systemPrompt = `You are an expert technical interviewer.`;
    let userPrompt = `Job Description: ${jobDescription}\n`;

    if (contextOrTopic.trim().startsWith('[')) {
      // It's history
      systemPrompt += ` Generate the next question based on the interview history. Maintain flow.`;
      userPrompt += `History: ${contextOrTopic}\n\nNext Question:`;
    } else {
      // It's a topic
      systemPrompt += ` Generate a challenging question on the topic.`;
      userPrompt += `Topic: ${contextOrTopic}\n\nQuestion:`;
    }

    return this.generateResponse(systemPrompt, userPrompt);
  }

  async evaluateAnswer(
    question: string,
    answer: string,
  ): Promise<{
    technicalScore: number;
    accuracyScore: number;
    communicationScore: number;
    confidenceScore: number;
    feedback: string;
  }> {
    const systemPrompt = `You are an expert technical interviewer. Evaluate the candidate's answer to the question.
     Return the result in JSON format with:
     - technicalScore (number 0-10)
     - accuracyScore (number 0-10)
     - communicationScore (number 0-10)
     - confidenceScore (number 0-10)
     - feedback (string, constructive feedback)
     Output ONLY valid JSON.`;

    const userPrompt = `Question: ${question}\nAnswer: ${answer}`;
    const response = await this.generateResponse(systemPrompt, userPrompt);
    try {
      const cleanJson = response
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      return JSON.parse(cleanJson);
    } catch (e) {
      return {
        technicalScore: 0,
        accuracyScore: 0,
        communicationScore: 0,
        confidenceScore: 0,
        feedback: 'Error evaluating answer',
      };
    }
  }

  async generateInterviewReport(interviewData: any): Promise<any> {
    const systemPrompt = `You are an expert technical recruiter. Analyze the interview transcript and provide a detailed report.
    Return ONLY valid JSON with no extra text.
    Format your response exactly as follows:
    {
      "overall_rating": 0-10,
      "technical_score": 0-10,
      "communication_score": 0-10,
      "problem_solving_score": 0-10,
      "behavioral_score": 0-10,
      "culture_fit_score": 0-10,
      "strengths": ["string"],
      "weaknesses": ["string"],
      "detailed_feedback": "Score: [0-100]\\nFeedback: [summary]\\nStrengths: [bullets]\\nAreas for Improvement: [bullets]",
      "fit_for_role": "YES" | "NO",
      "joining_probability_percent": 0-100
    }`;

    const userPrompt = `Job Title: ${interviewData.job}\nTranscript:\n${JSON.stringify(interviewData.messages)}`;
    const response = await this.generateResponse(systemPrompt, userPrompt);
    try {
      const cleanJson = response
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      return JSON.parse(cleanJson);
    } catch (e) {
      this.logger.error('Failed to parse interview report response', e);
      return {
        overall_rating: 0,
        technical_score: 0,
        communication_score: 0,
        problem_solving_score: 0,
        behavioral_score: 0,
        culture_fit_score: 0,
        strengths: ['Interview record available'],
        weaknesses: [
          'Interview too short or AI evaluation service unavailable',
        ],
        detailed_feedback:
          'Score: 0\\nFeedback: The interview was either too short to evaluate or the AI service encountered an error. Manual review of the transcript is recommended.',
        fit_for_role: 'NO',
        joining_probability_percent: 0,
      };
    }
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Job } from '../jobs/job.entity';
import { Candidate } from '../candidates/candidate.entity';
import { Interview } from '../interviews/entities/interview.entity';

@Injectable()
export class AnalyticsService {
  constructor(
    @InjectRepository(Job)
    private jobsRepository: Repository<Job>,
    @InjectRepository(Candidate)
    private candidatesRepository: Repository<Candidate>,
    @InjectRepository(Interview)
    private interviewsRepository: Repository<Interview>,
  ) {}

  async getDashboardMetrics() {
    const totalCandidates = await this.candidatesRepository.count();
    const activeJobs = await this.jobsRepository.count({
      where: { status: 'Active' },
    });
    const completedInterviews = await this.interviewsRepository.count({
      where: { status: 'completed' as any },
    }); // Standardized to lowercase

    // Average Score
    const interviewsWithScore = await this.interviewsRepository
      .createQueryBuilder('interview')
      .where('interview.score > 0')
      .getMany();

    const totalScore = interviewsWithScore.reduce(
      (sum, interview) => sum + interview.score,
      0,
    );
    const averageScore =
      interviewsWithScore.length > 0
        ? Math.round(totalScore / interviewsWithScore.length)
        : 0;

    return {
      totalCandidates,
      activeJobs,
      completedInterviews,
      averageScore,
      // Trends (mock for now because we don't have historical snapshots easily without more complex queries)
      trends: {
        candidates: { value: 12, label: 'from last month', positive: true },
        interviews: { value: 8, label: 'from last month', positive: true },
        score: { value: 2, label: 'improvement', positive: true },
        acceptance: { value: 5, label: 'from last month', positive: false },
      },
    };
  }
}

import { Controller, Get, Headers, UseGuards, Request } from '@nestjs/common';
import { AppService } from './app.service';
import { CombinedAuthGuard } from './auth/combined-auth.guard';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Get()
  getHello(): string {
    return this.appService.getHello();
  }

  // Debug endpoint - returns auth header and token info (REMOVE AFTER DEBUGGING)
  @Get('debug/auth-header')
  debugAuthHeader(@Headers('authorization') authHeader: string) {
    if (!authHeader) {
      return {
        status: 'NO TOKEN FOUND',
        header: null,
        hint: 'Authorization header is missing from the request',
      };
    }
    const tokenPreview = authHeader?.startsWith('Bearer ')
      ? authHeader.substring(7, 30) + '...'
      : 'Not a Bearer token';
    return {
      status: 'TOKEN RECEIVED',
      tokenPreview,
      headerLength: authHeader.length,
      startsWithBearer: authHeader.startsWith('Bearer '),
    };
  }

  // Debug endpoint - tests that the auth guard accepts the token
  @UseGuards(CombinedAuthGuard)
  @Get('debug/auth-test')
  debugAuthTest(@Request() req: any) {
    return { status: 'AUTH SUCCESSFUL', user: req.user };
  }
}

import { Module } from '@nestjs/common';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';
import { AuthModule } from './auth/auth.module';
import { JobsModule } from './jobs/jobs.module';
import { CandidatesModule } from './candidates/candidates.module';
import { InterviewsModule } from './interviews/interviews.module';
import { AIModule } from './ai/ai.module';
import { AnalyticsModule } from './analytics/analytics.module';
import { AppController } from './app.controller';
import { AppService } from './app.service';

import { GeminiModule } from './gemini/gemini.module';
import { DIdModule } from './did/did.module';
import { WebhooksModule } from './webhooks/webhooks.module';
import { InterviewAgentModule } from './interview-agent/interview-agent.module';

@Module({
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
    }),
    TypeOrmModule.forRootAsync({
      imports: [ConfigModule],
      useFactory: (configService: ConfigService) => ({
        type: 'postgres',
        host: configService.get<string>('DB_HOST'),
        port: configService.get<number>('DB_PORT'),
        username: configService.get<string>('DB_USER'),
        password: configService.get<string>('DB_PASSWORD'),
        database: configService.get<string>('DB_NAME'),
        entities: [__dirname + '/**/*.entity{.ts,.js}'],
        synchronize: true, // Creates tables on first run - disable after first deploy
        ssl:
          configService.get<string>('DB_HOST')?.includes('render.com') ||
          configService.get<string>('NODE_ENV') === 'production'
            ? { rejectUnauthorized: false }
            : false,
      }),
      inject: [ConfigService],
    }),
    AuthModule,
    JobsModule,
    CandidatesModule,
    InterviewsModule,
    AnalyticsModule,
    GeminiModule,
    DIdModule,
    WebhooksModule,
    InterviewAgentModule,
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}

import {
  Controller,
  Request,
  Post,
  UseGuards,
  Body,
  Get,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { AuthService } from './auth.service';

@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @UseGuards(AuthGuard('local'))
  @Post('login')
  async login(@Request() req) {
    return this.authService.login(req.user);
  }

  @Post('register')
  async register(@Body() body) {
    return this.authService.register(body);
  }

  @UseGuards(AuthGuard('jwt'))
  @Get('profile')
  getProfile(@Request() req) {
    return req.user;
  }

  @UseGuards(AuthGuard('jwt'))
  @Post('change-password')
  async changePassword(@Request() req, @Body() body) {
    return this.authService.changePassword(req.user.userId, body);
  }
}

import { Module } from '@nestjs/common';
import { AuthService } from './auth.service';
import { AuthController } from './auth.controller';
import { TypeOrmModule } from '@nestjs/typeorm';
import { User } from './user.entity';
import { Candidate } from '../candidates/candidate.entity';
import { PassportModule } from '@nestjs/passport';
import { JwtModule } from '@nestjs/jwt';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { JwtStrategy } from './jwt.strategy';
import { ClerkStrategy } from './clerk.strategy';
import { LocalStrategy } from './local.strategy';

@Module({
  imports: [
    TypeOrmModule.forFeature([User, Candidate]),
    PassportModule,
    JwtModule.registerAsync({
      imports: [ConfigModule],
      useFactory: async (configService: ConfigService) =>
        ({
          secret: configService.get<string>('JWT_SECRET'),
          signOptions: {
            expiresIn: configService.get<string>('JWT_EXPIRATION') || '1h',
          },
        }) as any,
      inject: [ConfigService],
    }),
  ],
  providers: [AuthService, LocalStrategy, JwtStrategy, ClerkStrategy],
  controllers: [AuthController],
  exports: [AuthService, JwtModule], // Export AuthService and JwtModule if needed elsewhere
})
export class AuthModule {}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import * as bcrypt from 'bcrypt';
import { ConfigService } from '@nestjs/config';
import { User, UserRole } from './user.entity';
import { Candidate } from '../candidates/candidate.entity';
import { createClerkClient } from '@clerk/backend';

@Injectable()
export class AuthService {
  private clerkClient;

  constructor(
    @InjectRepository(User)
    private usersRepository: Repository<User>,
    @InjectRepository(Candidate)
    private candidatesRepository: Repository<Candidate>,
    private jwtService: JwtService,
    private configService: ConfigService,
  ) {
    this.clerkClient = createClerkClient({
      secretKey: configService.get<string>('CLERK_SECRET_KEY'),
    });
  }

  async validateUser(email: string, pass: string): Promise<any> {
    const user = await this.usersRepository.findOne({
      where: { email },
      select: [
        'id',
        'email',
        'passwordHash',
        'role',
        'firstName',
        'lastName',
        'avatarUrl',
      ], // Explicitly select password
    });

    if (user && (await bcrypt.compare(pass, user.passwordHash))) {
      const { passwordHash, ...result } = user;
      return result;
    }
    return null;
  }

  async login(user: any) {
    const payload = { username: user.email, sub: user.id, role: user.role };
    return {
      access_token: this.jwtService.sign(payload),
      user: {
        id: user.id,
        email: user.email,
        role: user.role,
        firstName: user.firstName,
        lastName: user.lastName,
        avatarUrl: user.avatarUrl,
      },
    };
  }

  async register(registrationData: any) {
    const hashedPassword = await bcrypt.hash(registrationData.password, 10);
    const newUser = this.usersRepository.create({
      ...registrationData,
      passwordHash: hashedPassword,
    });
    const savedUser = (await this.usersRepository.save(
      newUser,
    )) as unknown as User;
    const { passwordHash, ...result } = savedUser;
    return result;
  }

  async syncClerkUser(data: any): Promise<User | null> {
    const { id: clerkId } = data;
    if (!clerkId) {
      console.warn('[ClerkSync] No Clerk ID provided in data');
      return null;
    }

    let email = data.email || data.email_addresses?.[0]?.email_address;
    let firstName = data.first_name || data.firstName || '';
    let lastName = data.last_name || data.lastName || '';
    let publicMetadata = data.public_metadata || {};
    let unsafeMetadata = data.unsafe_metadata || {};

    let extractedRole =
      publicMetadata?.role || unsafeMetadata?.role || data.role;

    // If email is missing (common with Clerk JWTs) OR role is missing (default JWT doesn't include metadata), fetch full user from Clerk API
    if (!email || !extractedRole) {
      try {
        console.log(
          `[ClerkSync] Metadata or Email missing in payload. Fetching full user from Clerk API for ${clerkId}`,
        );
        const clerkUser = await this.clerkClient.users.getUser(clerkId);
        email = clerkUser.emailAddresses?.[0]?.emailAddress || email;
        firstName = clerkUser.firstName || firstName;
        lastName = clerkUser.lastName || lastName;
        publicMetadata = {
          ...publicMetadata,
          ...clerkUser.publicMetadata,
        };
        unsafeMetadata = {
          ...unsafeMetadata,
          ...clerkUser.unsafeMetadata,
        };

        extractedRole =
          publicMetadata?.role || unsafeMetadata?.role || extractedRole;
        console.log(
          `[ClerkSync] Fetched full user details from Clerk API. Email: ${email}, Role: ${extractedRole}`,
        );
      } catch (err) {
        console.error(
          `[ClerkSync] Failed to fetch user from Clerk API: ${err.message}`,
        );
      }
    }

    console.log(
      `[ClerkSync] Starting sync for ClerkID: ${clerkId}, Email: ${email}, ExtractedRole: ${extractedRole}`,
    );

    let user = await this.usersRepository.findOne({
      where: { clerkId: clerkId },
    });

    if (user) {
      console.log(`[ClerkSync] Found existing user by ClerkID: ${user.id}`);
    }

    // If not found by clerkId, try to find by email and link them mapping legacy users
    if (!user && email) {
      user = await this.usersRepository.findOne({ where: { email } });
      if (user) {
        console.log(
          `[ClerkSync] Found legacy user by email: ${email}. Linking to ClerkID: ${clerkId}`,
        );
        user.clerkId = clerkId;
      }
    }

    const userData: Partial<User> = {
      clerkId: clerkId,
      firstName: firstName,
      lastName: lastName,
      avatarUrl:
        data.image_url || data.avatarUrl || data.profile_image_url || null,
      email: email || user?.email || `${clerkId}@clerk.local`,
    };

    if (!user) {
      console.log(
        `[ClerkSync] No user found. Creating new user record for ${userData.email}`,
      );
      const role = extractedRole || UserRole.CANDIDATE;

      user = this.usersRepository.create({
        ...userData,
        role: role as UserRole,
        passwordHash: 'CLERK_MANAGED',
      });
    } else {
      console.log(`[ClerkSync] Updating existing user: ${user.id}`);
      // ONLY override the user's role if Clerk explicitly provided one and it differs
      if (extractedRole && extractedRole !== user.role) {
        console.log(
          `[ClerkSync] Updating user role from ${user.role} to ${extractedRole}`,
        );
        userData.role = extractedRole as UserRole;
      }
      Object.assign(user, userData);
    }

    const savedUser = await this.usersRepository.save(user);
    console.log(
      `[ClerkSync] Successfully synchronized user: ${savedUser.email} (ID: ${savedUser.id}, Role: ${savedUser.role})`,
    );

    // ENSURE CANDIDATE PROFILE EXISTS
    if (
      savedUser.role === UserRole.CANDIDATE ||
      (savedUser.role as any) === 'candidate'
    ) {
      const candidateExists = await this.candidatesRepository.findOne({
        where: { userId: savedUser.id },
      });
      if (!candidateExists) {
        console.log(
          `[ClerkSync] Creating missing candidate profile for user: ${savedUser.id}`,
        );
        const newCandidate = this.candidatesRepository.create({
          userId: savedUser.id,
          location: 'Remote',
          resumeUrl: 'pending_upload',
        });
        await this.candidatesRepository.save(newCandidate);
      }
    }

    return savedUser;
  }

  async updateUser(userId: string, data: any) {
    await this.usersRepository.update(userId, data);
    return this.usersRepository.findOne({ where: { id: userId } });
  }
  async changePassword(userId: string, data: any) {
    if (!data.oldPassword || !data.newPassword) {
      throw new UnauthorizedException('Current and new password are required');
    }

    const user = await this.usersRepository.findOne({
      where: { id: userId },
      select: ['id', 'passwordHash'],
    });
    if (!user) throw new UnauthorizedException('User not found');

    const isMatch = await bcrypt.compare(data.oldPassword, user.passwordHash);
    if (!isMatch) throw new UnauthorizedException('Invalid old password');

    const hashedNewPassword = await bcrypt.hash(data.newPassword, 10);
    await this.usersRepository.update(userId, {
      passwordHash: hashedNewPassword,
    });
    return { message: 'Password updated successfully' };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-custom';
import { ConfigService } from '@nestjs/config';
import { AuthService } from './auth.service';
import { verifyToken } from '@clerk/backend';

@Injectable()
export class ClerkStrategy extends PassportStrategy(Strategy, 'clerk') {
  private secretKey: string;

  constructor(
    private configService: ConfigService,
    private authService: AuthService,
  ) {
    super();
    this.secretKey = configService.get<string>('CLERK_SECRET_KEY') || '';
  }

  async validate(req: any): Promise<any> {
    const authHeader = req.headers?.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      throw new UnauthorizedException('No Bearer token provided');
    }

    const token = authHeader.substring(7);

    try {
      // Verify the Clerk JWT using the official SDK
      const payload = await verifyToken(token, {
        secretKey: this.secretKey,
        // No authorizedParties restriction - let Clerk handle it
      });

      console.log('Clerk token verified successfully for sub:', payload?.sub);
      console.log(
        'Clerk Metadata:',
        JSON.stringify({
          public: payload?.publicMetadata,
          unsafe: (payload as any).unsafeMetadata,
        }),
      );

      if (!payload?.sub) {
        throw new UnauthorizedException('Invalid token payload');
      }

      // Sync or find the user in our database
      const user = await this.authService.syncClerkUser({
        id: payload.sub,
        email: (payload as any).email || '',
        email_addresses: [],
        first_name:
          (payload as any).firstName || (payload as any).given_name || '',
        last_name:
          (payload as any).lastName || (payload as any).family_name || '',
        image_url: null,
        public_metadata:
          (payload as any).publicMetadata || (payload as any).metadata || {},
      });

      if (!user) {
        throw new UnauthorizedException('User synchronization failed');
      }

      return {
        userId: user.id,
        username: user.email,
        role: user.role,
      };
    } catch (err) {
      // Log the actual Clerk error for debugging
      const errMessage = err?.message || err?.toString() || 'Unknown error';
      console.error('Clerk token verification failed:', errMessage);
      console.error('CLERK_SECRET_KEY set:', !!this.secretKey);
      throw new UnauthorizedException(
        `Token verification failed: ${errMessage}`,
      );
    }
  }
}

import { Injectable, ExecutionContext } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { firstValueFrom, Observable, isObservable } from 'rxjs';

@Injectable()
export class CombinedAuthGuard extends AuthGuard(['jwt', 'clerk']) {
  // This guard checks both strategies. Priority is given to local JWTs to prevent algorithm conflicts.
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    console.log(
      `[CombinedAuthGuard] Checking auth for: ${request.method} ${request.url}`,
    );
    try {
      const result = super.canActivate(context);
      const finalResult = isObservable(result)
        ? await firstValueFrom(result)
        : await result;

      console.log(
        `[CombinedAuthGuard] Auth success for ${request.url}: ${!!finalResult}`,
      );
      return !!finalResult;
    } catch (err) {
      console.error(
        `[CombinedAuthGuard] Auth FAILED for ${request.url}: ${err.message}`,
      );
      throw err;
    }
  }
}

import { ExtractJwt, Strategy } from 'passport-jwt';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy, 'jwt') {
  constructor(configService: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get<string>('JWT_SECRET') || 'secretKey',
    });
  }

  async validate(payload: any) {
    return {
      userId: payload.sub,
      username: payload.username,
      role: payload.role,
    };
  }
}

import { Strategy } from 'passport-local';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { AuthService } from './auth.service';

@Injectable()
export class LocalStrategy extends PassportStrategy(Strategy) {
  constructor(private authService: AuthService) {
    super({ usernameField: 'email' }); // Use email instead of username
  }

  async validate(email: string, password: string): Promise<any> {
    const user = await this.authService.validateUser(email, password);
    if (!user) {
      throw new UnauthorizedException();
    }
    return user;
  }
}

import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  UseGuards,
  Request,
  Param,
  UseInterceptors,
  UploadedFile,
} from '@nestjs/common';
import { CandidatesService } from './candidates.service';
import { CombinedAuthGuard } from '../auth/combined-auth.guard';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { extname } from 'path';

@Controller('candidates')
export class CandidatesController {
  constructor(private readonly candidatesService: CandidatesService) {}

  @UseGuards(CombinedAuthGuard)
  @Post('avatar-upload')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: './uploads',
        filename: (req, file, cb) => {
          const randomName = Array(32)
            .fill(null)
            .map(() => Math.round(Math.random() * 16).toString(16))
            .join('');
          cb(null, `${randomName}${extname(file.originalname)}`);
        },
      }),
    }),
  )
  async uploadAvatar(@UploadedFile() file: any, @Request() req) {
    const port = process.env.PORT || 3003;
    const apiBaseUrl = process.env.API_URL || `http://localhost:${port}`;
    const avatarUrl = `${apiBaseUrl}/uploads/${file.filename}`;

    // Update both User and Candidate for consistency
    await this.candidatesService.update(req.user.userId, { avatarUrl });

    return { avatarUrl };
  }

  @UseGuards(CombinedAuthGuard)
  @Post('resume-upload')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: diskStorage({
        destination: './uploads/resumes',
        filename: (req, file, cb) => {
          const randomName = Array(32)
            .fill(null)
            .map(() => Math.round(Math.random() * 16).toString(16))
            .join('');
          cb(null, `${randomName}${extname(file.originalname)}`);
        },
      }),
    }),
  )
  async uploadResume(@UploadedFile() file: any, @Request() req) {
    const port = process.env.PORT || 3003;
    const apiBaseUrl = process.env.API_URL || `http://localhost:${port}`;
    const fileUrl = `${apiBaseUrl}/uploads/resumes/${file.filename}`;

    return this.candidatesService.uploadResume(
      req.user.userId,
      file.path,
      fileUrl,
    );
  }

  @UseGuards(CombinedAuthGuard)
  @Post('profile')
  updateProfile(@Body() body: any, @Request() req) {
    return this.candidatesService.update(req.user.userId, body);
  }

  @UseGuards(CombinedAuthGuard)
  @Post()
  createCandidate(
    @Body()
    body: {
      firstName: string;
      lastName: string;
      email: string;
      resumeText: string;
    },
  ) {
    return this.candidatesService.createCandidateWithUser(
      body.firstName,
      body.lastName,
      body.email,
      body.resumeText,
    );
  }

  @UseGuards(CombinedAuthGuard)
  @Get('profile')
  getProfile(@Request() req) {
    return this.candidatesService.findOneByUserId(req.user.userId);
  }

  @UseGuards(CombinedAuthGuard)
  @Get()
  getAllCandidates() {
    return this.candidatesService.findAll();
  }

  @UseGuards(CombinedAuthGuard)
  @Post('parse-resume')
  async parseResume(@Body() body: { resumeText: string }) {
    return this.candidatesService.parseResume(body.resumeText);
  }

  @UseGuards(CombinedAuthGuard)
  @Get('applications')
  getMyApplications(@Request() req) {
    return this.candidatesService.getMyApplications(req.user.userId);
  }

  @UseGuards(CombinedAuthGuard)
  @Get('stats')
  getStats(@Request() req) {
    return this.candidatesService.getStats(req.user.userId);
  }

  @UseGuards(CombinedAuthGuard)
  @Get('experiences')
  getExperiences(@Request() req) {
    return this.candidatesService.getExperiences(req.user.userId);
  }

  @UseGuards(CombinedAuthGuard)
  @Post('experiences')
  addExperience(@Body() body: any, @Request() req) {
    return this.candidatesService.addExperience(req.user.userId, body);
  }

  @UseGuards(CombinedAuthGuard)
  @Patch('experiences/:id')
  updateExperience(@Param('id') id: string, @Body() body: any) {
    return this.candidatesService.updateExperience(id, body);
  }

  @UseGuards(CombinedAuthGuard)
  @Delete('experiences/:id')
  removeExperience(@Param('id') id: string) {
    return this.candidatesService.removeExperience(id);
  }

  @UseGuards(CombinedAuthGuard)
  @Get(':id/details')
  getCandidateDetails(@Param('id') id: string) {
    return this.candidatesService.findOneWithDetails(id);
  }

  @UseGuards(CombinedAuthGuard)
  @Post('applications/:id/status')
  updateApplicationStatus(
    @Param('id') id: string,
    @Body('status') status: string,
  ) {
    return this.candidatesService.updateApplicationStatus(id, status);
  }

  @UseGuards(CombinedAuthGuard)
  @Get(':id')
  getOne(@Param('id') id: string) {
    return this.candidatesService.findOne(id);
  }

  @UseGuards(CombinedAuthGuard)
  @Post('apply/:jobId')
  apply(@Param('jobId') jobId: string, @Request() req) {
    return this.candidatesService.applyToJob(req.user.userId, jobId);
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';
import * as fs from 'fs';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { Candidate } from './candidate.entity';
import { Application, ApplicationStatus } from './application.entity';
import { OpenAIService } from '../ai/openai.service';
import { AuthService } from '../auth/auth.service';
import { Job } from '../jobs/job.entity';
import { ScoringService } from '../scoring/scoring.service';
const pdf = require('pdf-parse');

import { Interview } from '../interviews/entities/interview.entity';
import { CandidateExperience } from './experience.entity';
import { ResumeParserService } from '../interviews/question-generation/resume-parser.service';
import { SkillMatchingService } from '../interviews/question-generation/skill-matching.service';
import { QuestionGenerationService } from '../interviews/question-generation/question-generation.service';

@Injectable()
export class CandidatesService {
  constructor(
    @InjectRepository(Candidate)
    private candidatesRepository: Repository<Candidate>,
    @InjectRepository(Application)
    private applicationsRepository: Repository<Application>,
    @InjectRepository(Job)
    private jobsRepository: Repository<Job>,
    @InjectRepository(Interview)
    private interviewsRepository: Repository<Interview>,
    @InjectRepository(CandidateExperience)
    private experienceRepository: Repository<CandidateExperience>,
    private openAIService: OpenAIService,
    private authService: AuthService,
    private scoringService: ScoringService,
    private resumeParserService: ResumeParserService,
    private skillMatchingService: SkillMatchingService,
    private questionGenerationService: QuestionGenerationService,
    private dataSource: DataSource,
  ) {}

  async create(createCandidateDto: any, userId: string): Promise<Candidate> {
    const candidate = this.candidatesRepository.create({
      ...createCandidateDto,
      userId,
    });
    return this.candidatesRepository.save(
      candidate,
    ) as unknown as Promise<Candidate>;
  }

  async createCandidateWithUser(
    firstName: string,
    lastName: string,
    email: string,
    resumeText: string,
  ): Promise<Candidate> {
    // 1. Create User
    const password = 'tempPassword123!';
    let user;

    try {
      user = await this.authService.register({
        email,
        password,
        firstName,
        lastName,
        role: 'candidate',
      });
    } catch (error) {
      throw new Error(
        `User with email ${email} already exists or failed to create.`,
      );
    }

    // 2. Parse Resume (Local)
    const parsedData = this.basicParseResume(resumeText);

    // 3. Create Candidate Profile
    const candidateData = {
      userId: user.id,
      skills: parsedData.skills || [],
      experienceYears: parsedData.experienceYears || 0,
      resumeUrl: 'pending_upload',
      location: 'Remote',
    };

    return this.create(candidateData, user.id);
  }

  async findAll(): Promise<Candidate[]> {
    return this.candidatesRepository.find({ relations: ['user'] });
  }

  async findOneByUserId(userId: string): Promise<Candidate | null> {
    return this.candidatesRepository.findOne({
      where: { userId },
      relations: ['user'],
    });
  }

  async findOne(id: string): Promise<Candidate | null> {
    return this.candidatesRepository.findOne({
      where: { id },
      relations: ['user'],
    });
  }

  async update(userId: string, updateCandidateDto: any): Promise<Candidate> {
    const { firstName, lastName, avatarUrl, ...candidateData } =
      updateCandidateDto;

    if (firstName || lastName || avatarUrl) {
      await this.authService.updateUser(userId, {
        firstName,
        lastName,
        avatarUrl,
      });
    }

    const candidate = await this.findOneByUserId(userId);
    if (candidate) {
      const updatePayload = avatarUrl
        ? { ...candidateData, avatarUrl }
        : candidateData;
      await this.candidatesRepository.update(candidate.id, updatePayload);
      const updated = await this.findOneByUserId(userId);
      if (!updated) throw new Error('Candidate not found after update');
      return updated;
    }

    return this.create(candidateData, userId);
  }

  basicParseResume(resumeText: string): any {
    const text = resumeText.toLowerCase();
    const commonSkills = [
      'javascript',
      'typescript',
      'react',
      'nodejs',
      'nest',
      'python',
      'java',
      'sql',
      'docker',
      'aws',
      'azure',
      'ai',
      'blockchain',
      'php',
      'sap',
      'security',
    ];
    const extractedSkills = commonSkills.filter((skill) =>
      text.includes(skill),
    );

    // Very basic experience extraction (looking for "X years")
    const expMatch = text.match(/(\d+)\s*(?:years|yr|years of experience)/i);
    const experienceYears = expMatch ? parseInt(expMatch[1]) : 0;

    return {
      skills: extractedSkills,
      experienceYears,
    };
  }

  async parseResume(resumeText: string): Promise<any> {
    return this.basicParseResume(resumeText);
  }

  async uploadResume(
    userId: string,
    filePath: string,
    fileUrl: string,
  ): Promise<Candidate> {
    const dataBuffer = fs.readFileSync(filePath);
    const data = await pdf(dataBuffer);
    const resumeText = data.text;

    const parsedData = this.basicParseResume(resumeText);

    const candidate = await this.findOneByUserId(userId);
    if (candidate) {
      await this.candidatesRepository.update(candidate.id, {
        resumeText,
        resumeUrl: fileUrl,
        skills: parsedData.skills || candidate.skills,
        experienceYears:
          parsedData.experienceYears || candidate.experienceYears,
      });
      const updated = await this.findOneByUserId(userId);
      if (!updated) throw new Error('Candidate not found after update');
      return updated;
    }

    const candidateData = {
      userId,
      resumeText,
      resumeUrl: fileUrl,
      skills: parsedData.skills || [],
      experienceYears: parsedData.experienceYears || 0,
      location: 'Remote',
    };

    return this.create(candidateData, userId);
  }

  // Application Methods
  async applyToJob(userId: string, jobId: string): Promise<Application> {
    const candidate = await this.findOneByUserId(userId);

    if (!candidate) throw new NotFoundException('Candidate profile not found.');
    if (!candidate.resumeText)
      throw new BadRequestException(
        'Resume upload is mandatory before applying.',
      );

    // Check if already applied
    const existing = await this.applicationsRepository.findOne({
      where: { candidateId: candidate.id, jobId },
    });

    if (existing) throw new BadRequestException('Already applied to this job.');

    const job = await this.jobsRepository.findOne({ where: { id: jobId } });
    if (!job) throw new NotFoundException('Job not found.');

    // AI Scoring
    const scoringResult = await this.scoringService.evaluateResume(
      candidate.resumeText,
      job.description,
    );

    const isEligible = scoringResult.resumeScore >= 40;
    let interviewQuestions: string[] = [];
    let parsedResume: any = null;

    if (isEligible) {
      try {
        // 1. Parse Resume
        parsedResume = await this.resumeParserService.parse(
          candidate.resumeText,
        );

        // 2. Skill Matching
        const skillMatch = this.skillMatchingService.match(
          job.requiredSkills || [],
          parsedResume.skills || [],
        );

        // 3. Generate Questions
        interviewQuestions =
          await this.questionGenerationService.generate20Questions(
            parsedResume,
            skillMatch,
            job.title,
          );
      } catch (err) {
        console.error('Failed to pre-generate questions:', err);
        // Fallback: empty array, will handle during session if needed
      }
    }

    const application = this.applicationsRepository.create({
      candidateId: candidate.id,
      jobId,
      resumeScore: scoringResult.resumeScore,
      resumeBreakdown: scoringResult.resumeBreakdown,
      category: scoringResult.category,
      shortlisted: isEligible,
      interviewUnlocked: isEligible,
      status: isEligible
        ? ApplicationStatus.INTERVIEW_ELIGIBLE
        : ApplicationStatus.REJECTED_AI,
      interviewQuestions,
      parsedResume,
      interviewStatus: isEligible ? 'ready' : 'not_started',
    });

    const savedApp = await this.applicationsRepository.save(application);

    // Update Ranks for this job
    await this.updateRanks(jobId);

    return this.applicationsRepository.findOne({
      where: { id: savedApp.id },
    }) as Promise<Application>;
  }

  async updateRanks(jobId: string): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      const applications = await manager.find(Application, {
        where: { jobId },
        order: { resumeScore: 'DESC' },
      });

      for (let i = 0; i < applications.length; i++) {
        await manager.update(Application, applications[i].id, { rank: i + 1 });
      }
    });
  }

  async getMyApplications(userId: string): Promise<any[]> {
    const candidate = await this.findOneByUserId(userId);
    if (!candidate) return [];

    const apps = await this.applicationsRepository.find({
      where: { candidateId: candidate.id },
      relations: ['job'],
    });

    return apps.map((app) => {
      const isTopTalent = app.rank !== null && app.rank <= 3;
      const canSeeDetails = app.resumeScore >= 40;

      const baseApp = {
        id: app.id,
        jobId: app.jobId,
        job: app.job,
        createdAt: app.createdAt,
        status: app.status,
        rank: app.rank,
        isTopTalent,
      };

      if (canSeeDetails) {
        return {
          ...baseApp,
          resumeScore: app.resumeScore,
          resumeBreakdown: app.resumeBreakdown,
          category: app.category,
        };
      } else {
        return {
          ...baseApp,
          message: 'Application under review',
        };
      }
    });
  }

  async getStats(userId: string): Promise<any> {
    const candidate = await this.findOneByUserId(userId);
    if (!candidate)
      return {
        totalApplications: 0,
        interviewsCompleted: 0,
        avgScore: 0,
        profileStrength: 0,
      };

    const apps = await this.applicationsRepository.find({
      where: { candidateId: candidate.id },
    });

    const statusCounts = {
      underReview: apps.filter((a) => a.status === ApplicationStatus.APPLIED)
        .length,
      eligible: apps.filter(
        (a) => a.status === ApplicationStatus.INTERVIEW_ELIGIBLE,
      ).length,
      interviews: apps.filter(
        (a) =>
          a.status === ApplicationStatus.INTERVIEWED ||
          a.status === ApplicationStatus.INTERVIEW_ELIGIBLE,
      ).length,
      rejected: apps.filter(
        (a) =>
          a.status === ApplicationStatus.REJECTED ||
          a.status === ApplicationStatus.REJECTED_AI ||
          a.status === ApplicationStatus.REJECTED_POST_INTERVIEW,
      ).length,
      selected: apps.filter((a) => a.status === ApplicationStatus.SELECTED)
        .length,
    };

    // Calculate Profile Strength
    let strength = 0;
    const isSet = (val: any) => val && val.toString().trim().length > 0;

    if (isSet(candidate.resumeText)) strength += 30;
    if (isSet(candidate.avatarUrl)) strength += 10;
    if (isSet(candidate.bio)) strength += 10;
    if (isSet(candidate.location)) strength += 10;
    if (isSet(candidate.linkedinUrl)) strength += 10;
    if (isSet(candidate.portfolioUrl)) strength += 10;
    if (candidate.skills && candidate.skills.length > 0) strength += 10;
    if (candidate.experienceYears > 0) strength += 10;

    return {
      totalApplications: apps.length,
      interviewsCompleted: apps.filter((a) =>
        [
          ApplicationStatus.INTERVIEWED,
          ApplicationStatus.SELECTED,
          ApplicationStatus.HOLD,
          ApplicationStatus.REJECTED_POST_INTERVIEW,
        ].includes(a.status as ApplicationStatus),
      ).length,
      avgScore:
        apps.length > 0
          ? Math.round(
              apps.reduce((acc, curr) => acc + (curr.resumeScore || 0), 0) /
                apps.length,
            )
          : 0,
      profileStrength: Math.min(strength, 100),
      statusCounts,
    };
  }

  // New Detailed Methods for Recruiter
  async findOneWithDetails(id: string): Promise<any> {
    const candidate = await this.candidatesRepository.findOne({
      where: { id },
      relations: ['user', 'experiences'],
    });

    if (!candidate) throw new NotFoundException('Candidate not found');

    const applications = await this.applicationsRepository.find({
      where: { candidateId: candidate.id },
      relations: ['job'],
      order: { createdAt: 'DESC' },
    });

    const interviews = await this.interviewsRepository.find({
      where: { candidateId: candidate.id },
      relations: ['job', 'report'],
      order: { createdAt: 'DESC' },
    });

    return {
      ...candidate,
      applications,
      interviews,
    };
  }

  async addExperience(
    userId: string,
    experienceDto: any,
  ): Promise<CandidateExperience> {
    const candidate = await this.findOneByUserId(userId);
    if (!candidate) throw new NotFoundException('Candidate not found');

    // Basic normalization
    const experience = new CandidateExperience();
    experience.employer = experienceDto.employer;
    experience.role = experienceDto.role;

    // Handle dates: convert empty strings to null
    experience.startDate =
      experienceDto.startDate && experienceDto.startDate.trim() !== ''
        ? new Date(experienceDto.startDate)
        : null;

    experience.endDate =
      experienceDto.endDate && experienceDto.endDate.trim() !== ''
        ? new Date(experienceDto.endDate)
        : null;

    experience.description =
      experienceDto.description && experienceDto.description.trim() !== ''
        ? experienceDto.description
        : null;

    experience.isCurrent = experienceDto.isCurrent || false;
    experience.candidateId = candidate.id;

    // Validation
    if (!experience.employer || !experience.role || !experience.startDate) {
      throw new BadRequestException(
        'Employer, role, and valid start date are required',
      );
    }

    return this.experienceRepository.save(experience);
  }

  async updateExperience(
    id: string,
    experienceDto: any,
  ): Promise<CandidateExperience> {
    // Normalize fields for update too
    const updatePayload: any = { ...experienceDto };

    if (updatePayload.startDate === '') updatePayload.startDate = null;
    if (updatePayload.endDate === '') updatePayload.endDate = null;
    if (updatePayload.description === '') updatePayload.description = null;

    await this.experienceRepository.update(id, updatePayload);
    const updated = await this.experienceRepository.findOne({ where: { id } });
    if (!updated) throw new NotFoundException('Experience not found');
    return updated;
  }

  async removeExperience(id: string): Promise<void> {
    await this.experienceRepository.delete(id);
  }

  async getExperiences(userId: string): Promise<CandidateExperience[]> {
    const candidate = await this.findOneByUserId(userId);
    if (!candidate) return [];
    return this.experienceRepository.find({
      where: { candidateId: candidate.id },
      order: { startDate: 'DESC' },
    });
  }

  async updateApplicationStatus(
    applicationId: string,
    status: string,
  ): Promise<Application> {
    const application = await this.applicationsRepository.findOne({
      where: { id: applicationId },
    });
    if (!application) throw new NotFoundException('Application not found');

    // Validate status
    if (
      !Object.values(ApplicationStatus).includes(status as ApplicationStatus)
    ) {
      throw new BadRequestException('Invalid application status');
    }

    application.status = status;
    return this.applicationsRepository.save(application);
  }
}

import {
  Entity,
  Column,
  PrimaryGeneratedColumn,
  CreateDateColumn,
  UpdateDateColumn,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { Candidate } from './candidate.entity';

@Entity('resumes')
export class Resume {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column('uuid')
  candidateId: string;

  @ManyToOne(() => Candidate)
  @JoinColumn({ name: 'candidateId' })
  candidate: Candidate;

  @Column()
  fileUrl: string;

  @Column('text', { nullable: true })
  extractedText: string;

  @CreateDateColumn()
  uploadedAt: Date;
}

import {
  Controller,
  Post,
  Body,
  Param,
  Delete,
  Query,
  UseGuards,
  Request,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { DIdService } from './did.service';
import { DIdSessionManager } from './did-session.manager';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Application } from '../candidates/application.entity';
import { CombinedAuthGuard } from '../auth/combined-auth.guard';

@Controller('did')
export class DIdController {
  constructor(
    private readonly didService: DIdService,
    private readonly didSessionManager: DIdSessionManager,
    @InjectRepository(Application)
    private applicationsRepository: Repository<Application>,
  ) {}

  @UseGuards(CombinedAuthGuard)
  @Post('session')
  async createSession(
    @Body('source_url') sourceUrl: string,
    @Query('interviewId') interviewId: string,
    @Request() req,
  ) {
    // Eligibility check (Relaxed for development to allow testing without strict resume scores)
    const application = await this.applicationsRepository.findOne({
      where: { candidate: { userId: req.user.userId } },
      relations: ['candidate'],
    });

    if (!application) {
      console.warn(
        `D-ID: No active application found for user ${req.user.userId}. Proceeding for development.`,
      );
      // throw new NotFoundException('No active application found for this user');
    } else if (application.resumeScore < 40) {
      console.warn(
        `D-ID: Resume score (${application.resumeScore}) is low for user ${req.user.userId}. Proceeding for development.`,
      );
      // throw new ForbiddenException('Interview eligibility not met (resumeScore < 40)');
    }

    // Proactive cleanup: If a session already exists for this interview, close it first
    if (interviewId) {
      const existingSession = this.didSessionManager.getSession(interviewId);
      if (existingSession) {
        console.log(
          `D-ID: Proactively closing existing session for interview ${interviewId}`,
        );
        await this.didService
          .closeSession(existingSession.streamId, existingSession.sessionId)
          .catch(() => {});
        this.didSessionManager.removeSession(interviewId);
      }
    }

    // Default source URL if none provided (using the one from the working demo)
    const url =
      sourceUrl ||
      's3://d-id-images-prod/google-oauth2|113431953721122947261/img__xooWJIsTGKb5ZlbrrGXu/indian-avatar.png';

    const session = await this.didService.createSession(url);

    if (interviewId) {
      this.didSessionManager.setSession(interviewId, {
        sessionId: session.session_id,
        streamId: session.id,
      });
    }

    return session;
  }

  @UseGuards(CombinedAuthGuard)
  @Post('session/:streamId/sdp')
  async startStream(
    @Param('streamId') streamId: string,
    @Body('session_id') sessionId: string,
    @Body('answer') answer: any,
  ) {
    return this.didService.startStream(streamId, sessionId, answer);
  }

  @UseGuards(CombinedAuthGuard)
  @Post('session/:streamId/ice')
  async submitIceCandidate(
    @Param('streamId') streamId: string,
    @Body('session_id') sessionId: string,
    @Body('candidate') candidate: any,
  ) {
    return this.didService.submitIceCandidate(streamId, sessionId, candidate);
  }

  @UseGuards(CombinedAuthGuard)
  @Delete('session/:streamId')
  async closeSession(
    @Param('streamId') streamId: string,
    @Body('session_id') sessionId: string,
    @Query('interviewId') interviewId: string,
  ) {
    if (interviewId) {
      this.didSessionManager.removeSession(interviewId);
    }
    return this.didService.closeSession(streamId, sessionId);
  }
}

import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios from 'axios';
import * as https from 'https';

@Injectable()
export class DIdService {
  private readonly apiKey: string | undefined;
  private readonly baseUrl = 'https://api.d-id.com';
  private readonly httpsAgent = new https.Agent({
    rejectUnauthorized: false, // Bypass SSL issues (e.g. self-signed certificate chain)
  });

  constructor(private configService: ConfigService) {
    this.apiKey = this.configService.get<string>('DID_API_KEY');
    const keyStatus = this.apiKey
      ? `PRESENT (len=${this.apiKey.length}, ends with ${this.apiKey.slice(-4)})`
      : 'MISSING';
    console.log(`D-ID Service Initialized. Key: ${keyStatus}`);
  }

  private getHeaders() {
    // Use the apiKey directly as it is already formatted for Basic Auth (as seen in demo)
    return {
      Authorization: `Basic ${this.apiKey}`,
      'Content-Type': 'application/json',
      accept: 'application/json',
    };
  }

  async createSession(sourceUrl: string) {
    return this.requestWithRetry(
      () =>
        axios.post(
          `${this.baseUrl}/talks/streams`,
          { source_url: sourceUrl, stream_warmup: true },
          {
            headers: this.getHeaders(),
            httpsAgent: this.httpsAgent,
          },
        ),
      'CreateSession',
    );
  }

  async startStream(streamId: string, sessionId: string, answer: any) {
    return this.requestWithRetry(
      () =>
        axios.post(
          `${this.baseUrl}/talks/streams/${streamId}/sdp`,
          { answer, session_id: sessionId },
          {
            headers: this.getHeaders(),
            httpsAgent: this.httpsAgent,
          },
        ),
      'StartStream',
    );
  }

  async submitIceCandidate(
    streamId: string,
    sessionId: string,
    candidate: any,
  ) {
    // D-ID API expects a flat object with candidate, sdpMid, sdpMLineIndex, and session_id
    const body = candidate
      ? {
          candidate: candidate.candidate,
          sdpMid: candidate.sdpMid,
          sdpMLineIndex: candidate.sdpMLineIndex,
          session_id: sessionId,
        }
      : { session_id: sessionId };

    return this.requestWithRetry(
      () =>
        axios.post(`${this.baseUrl}/talks/streams/${streamId}/ice`, body, {
          headers: this.getHeaders(),
          httpsAgent: this.httpsAgent,
        }),
      'SubmitIce',
    );
  }

  async speak(sessionId: string, streamId: string, text: string) {
    return this.requestWithRetry(
      () =>
        axios.post(
          `${this.baseUrl}/talks/streams/${streamId}`,
          {
            script: {
              type: 'text',
              subtitles: false,
              provider: {
                type: 'microsoft',
                voice_id: 'en-US-AndrewNeural',
              },
              ssml: false,
              input: text,
            },
            config: {
              fluent: false,
              pad_audio: 0.0,
              stitch: true,
            },
            session_id: sessionId,
          },
          {
            headers: this.getHeaders(),
            httpsAgent: this.httpsAgent,
          },
        ),
      'Speak',
    );
  }

  async closeSession(streamId: string, sessionId: string) {
    try {
      await this.requestWithRetry(
        () =>
          axios.delete(`${this.baseUrl}/talks/streams/${streamId}`, {
            data: { session_id: sessionId },
            headers: this.getHeaders(),
            httpsAgent: this.httpsAgent,
          }),
        'CloseSession',
      );
    } catch (error) {
      console.error('D-ID CloseSession Error (ignored):', error.message);
    }
  }

  private async requestWithRetry(
    requestFn: () => Promise<any>,
    actionName: string,
    retries = 3,
    delay = 1000,
  ) {
    for (let i = 0; i < retries; i++) {
      try {
        if (actionName === 'CreateSession') {
          console.log(`D-ID: ${actionName} initiating...`);
        }
        const response = await requestFn();
        if (actionName === 'CreateSession') {
          console.log(`D-ID: ${actionName} Success:`, response.data.id);
        }
        return response.data;
      } catch (error) {
        const status = error.response?.status;
        const errorData = error.response?.data;

        if (status === 429 && i < retries - 1) {
          console.warn(
            `D-ID ${actionName} 429 (Rate Limit). Retrying in ${delay / 1000}s... (Attempt ${i + 1}/${retries})`,
          );
          await new Promise((resolve) => setTimeout(resolve, delay));
          delay *= 2; // Exponential backoff
          continue;
        }

        console.error(`D-ID ${actionName} Error:`, {
          status,
          data: JSON.stringify(errorData),
          message: error.message,
        });

        let errorMessage =
          errorData?.description ||
          errorData?.message ||
          `Failed to perform D-ID ${actionName}`;
        if (
          status === 403 &&
          errorMessage.toLowerCase().includes('max user sessions')
        ) {
          errorMessage =
            'D-ID concurrent session limit reached. Please close other active interview tabs or wait a minute for the previous session to timeout.';
        }

        throw new HttpException(
          errorMessage,
          status || HttpStatus.INTERNAL_SERVER_ERROR,
        );
      }
    }
  }
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { GoogleGenerativeAI, GenerativeModel } from '@google/generative-ai';

export interface QuestionData {
  question: string;
  skillFocus: string;
  difficulty: string;
}

export interface EvaluationData {
  technicalScore: number;
  accuracyScore: number;
  communicationScore: number;
  confidenceScore: number;
  feedback: string;
}

export interface ReportData {
  overallScore: number;
  strengths: string[];
  weaknesses: string[];
  recommendation: string;
  detailedAnalysis: any;
}

@Injectable()
export class GeminiService {
  private models: GenerativeModel[] = [];
  private currentKeyIndex = 0;

  constructor(private configService: ConfigService) {
    const keys = [
      this.configService.get<string>('GEMINI_API_KEY'),
      this.configService.get<string>('GEMINI_API_KEY2'),
      this.configService.get<string>('GEMINI_API_KEY3'),
      this.configService.get<string>('GEMINI_API_KEY4'),
      this.configService.get<string>('GEMINI_API_KEY5'),
    ].filter((k) => !!k) as string[];

    if (keys.length === 0) {
      console.warn('No GEMINI_API_KEYs found in environment variables');
    } else {
      this.models = keys.map((key) => {
        const genAI = new GoogleGenerativeAI(key);
        return genAI.getGenerativeModel({ model: 'gemini-2.5-flash' });
      });
      console.log(
        `Initialized GeminiService with ${this.models.length} API keys.`,
      );
    }
  }

  private async runWithRotation<T>(
    action: (model: GenerativeModel) => Promise<T>,
    fallback: T,
  ): Promise<T> {
    let attempts = 0;
    const maxAttempts = this.models.length;

    if (maxAttempts === 0) {
      throw new Error('Gemini models not initialized. Check API Keys.');
    }

    while (attempts < maxAttempts) {
      const model = this.models[this.currentKeyIndex];
      try {
        return await action(model);
      } catch (error: any) {
        attempts++;
        console.error(
          `Error with Gemini Key #${this.currentKeyIndex + 1}: ${error.message}`,
        );

        // Check for rate limit (429) or other retryable errors
        const isRetryable =
          error.message?.includes('429') ||
          error.status === 429 ||
          error.status >= 500;

        if (isRetryable && attempts < maxAttempts) {
          this.currentKeyIndex =
            (this.currentKeyIndex + 1) % this.models.length;
          console.warn(
            `Switching to Gemini API Key #${this.currentKeyIndex + 1} (Attempt ${attempts + 1}/${maxAttempts})`,
          );
          continue;
        }

        // If we've exhausted keys or error is not retryable, use fallback or throw
        break;
      }
    }

    console.warn('Gemini exhausted all keys, using fallback.');
    return fallback;
  }

  private fallbackQuestions: (QuestionData & { isComplete: boolean })[] = [
    {
      question: 'Tell me about yourself and your professional background.',
      skillFocus: 'Communication',
      difficulty: 'Easy',
