              "fit_for_role": "YES" | "NO",
              "joining_probability_percent": 0-100
            }
        `;

    const fallback = {
      technical_score: 0,
      communication_score: 0,
      problem_solving_score: 0,
      behavioral_score: 0,
      culture_fit_score: 0,
      overall_rating: 0,
      strengths: ['Interview record available'],
      weaknesses: ['Interview too short or AI evaluation service unavailable'],
      detailed_feedback:
        'Score: 0\nFeedback: The interview was either too short to evaluate or the AI service encountered an error. Manual review of the transcript is recommended.',
      fit_for_role: 'NO',
      confidence_level: 'Low',
      joining_probability_percent: 0,
      joining_reasoning: 'Incomplete or failed AI analysis.',
    };

    return this.runWithRotation(async (model) => {
      const result = await model.generateContent(prompt);
      return this.cleanJson(result.response.text());
    }, fallback);
  }

  async refineInterviewQuestions(
    questions: string[],
    resume: any,
    jobTitle: string,
  ): Promise<string[]> {
    const prompt = `
            You are a Senior Technical Recruiter. I have a list of 20 interview questions for a ${jobTitle} position.
            Candidate Summary: ${JSON.stringify(resume)}

            Original Questions:
            ${questions.map((q, i) => `${i + 1}. ${q}`).join('\n')}

            Tasks:
            1. Improve the phrasing to be more professional, natural, and diverse.
            2. Increase the technical depth based on the candidate's specific background.
            3. Ensure each question is a SINGLE technical question (no combined questions).
            4. **CRITICAL: DO NOT start every question with the same phrase.**
               - BAD: "Explain how you...", "Explain how you..."
               - GOOD: Vary your openers: "Walk me through...", "How do you approach...", "In your experience with...", "Tell me about...", "Describe a time when..."
            5. Keep exactly 20 questions.
            6. Return ONLY a JSON array of strings.

            Format: ["Question 1", "Question 2", ...]
        `;

    const fallback = questions;

    return this.runWithRotation(async (model) => {
      const result = await model.generateContent(prompt);
      const text = result.response.text();
      const cleaned = this.cleanJson(text);
      if (Array.isArray(cleaned) && cleaned.length === 20) {
        return cleaned;
      }
      return fallback;
    }, fallback);
  }

  private cleanJson(text: string): any {
    try {
      // Remove markdown code blocks if present
      const cleaned = text
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      // Try to find the first [ and last ]
      const start = cleaned.indexOf('[');
      const end = cleaned.lastIndexOf(']');
      if (start !== -1 && end !== -1) {
        return JSON.parse(cleaned.substring(start, end + 1));
      }
      // For objects
      const objStart = cleaned.indexOf('{');
      const objEnd = cleaned.lastIndexOf('}');
      if (objStart !== -1 && objEnd !== -1) {
        return JSON.parse(cleaned.substring(objStart, objEnd + 1));
      }
      return JSON.parse(cleaned);
    } catch (e) {
      console.error('Failed to parse Gemini JSON response:', text);
      throw new Error('Invalid JSON from AI');
    }
  }

  async evaluateResume(
    resumeText: string,
    jobDescription: string,
  ): Promise<any> {
    const prompt = `You are an expert technical recruiter.
Compare the following resume with the job description.
Score from 0 to 100 based on fit.
Be objective but fair. For students or early-career candidates, look for relevant coursework, projects, and potential.
If the resume is extremely brief (e.g., only a name), provide low but realistic scores if any keywords match.
Return JSON only in this format:
{
  "skillMatchScore": number,
  "experienceMatch": number,
  "relevanceScore": number,
  "overallScore": number,
  "strengths": string[],
  "weaknesses": string[]
}

Job Description:
${jobDescription}

Resume:
${resumeText}`;

    const fallback = {
      skillMatchScore: 0,
      experienceMatch: 0,
      relevanceScore: 0,
      overallScore: 0,
      strengths: ['Unable to evaluate'],
      weaknesses: ['AI service unavailable'],
    };

    return this.runWithRotation(async (model) => {
      const result = await model.generateContent(prompt);
      const text = result.response.text();
      return this.cleanJson(text);
    }, fallback);
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
  OnGatewayConnection,
  OnGatewayDisconnect,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger, UseGuards } from '@nestjs/common';

@WebSocketGateway({ namespace: '/recruiter-monitor', cors: true })
export class LiveInterviewGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(LiveInterviewGateway.name);

  handleConnection(client: Socket) {
    this.logger.log(`Client connected to monitor gateway: ${client.id}`);
    const token = client.handshake.auth?.token;
    this.logger.debug(`Connection auth token present: ${!!token}`);
  }

  handleDisconnect(client: Socket) {
    this.logger.log(`Client disconnected from monitor gateway: ${client.id}`);
  }

  @SubscribeMessage('join-room')
  handleJoinRoom(
    @ConnectedSocket() client: Socket,
    @MessageBody()
    data: { interviewId: string; role: 'candidate' | 'recruiter' },
  ) {
    const room = `interview:${data.interviewId}`;
    client.join(room);
    this.logger.log(`${data.role} (${client.id}) joined room: ${room}`);

    // Notify others in the room so they can initiate WebRTC
    client.to(room).emit('user-joined', { role: data.role });

    return { event: 'joined', room };
  }

  // --- WEBRTC SIGNALING ---

  @SubscribeMessage('candidate-offer')
  handleCandidateOffer(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { interviewId: string; offer: any },
  ) {
    this.logger.debug(
      `Relaying WebRTC Offer for interview ${data.interviewId}`,
    );
    client
      .to(`interview:${data.interviewId}`)
      .emit('candidate-offer', { offer: data.offer });
  }

  @SubscribeMessage('recruiter-answer')
  handleRecruiterAnswer(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { interviewId: string; answer: any },
  ) {
    this.logger.debug(
      `Relaying WebRTC Answer for interview ${data.interviewId}`,
    );
    client
      .to(`interview:${data.interviewId}`)
      .emit('recruiter-answer', { answer: data.answer });
  }

  @SubscribeMessage('ice-candidate')
  handleIceCandidate(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { interviewId: string; candidate: any },
  ) {
    this.logger.debug(
      `Relaying ICE Candidate for interview ${data.interviewId}`,
    );
    client
      .to(`interview:${data.interviewId}`)
      .emit('ice-candidate', { candidate: data.candidate });
  }

  // --- BROADCAST HELPERS FOR SERVICES ---

  broadcastInterviewStarted(data: any) {
    this.logger.log(`Broadcasting interview started: ${data.interviewId}`);
    if (!this.server) {
      this.logger.error(
        'Socket.io server NOT initialized in LiveInterviewGateway!',
      );
      return;
    }
    this.server.emit('interview:started', data);
  }

  broadcastQuestion(interviewId: string, text: string) {
    this.logger.debug(`Broadcasting question to interview:${interviewId}`);
    this.server
      .to(`interview:${interviewId}`)
      .emit('interview:question', { text, timestamp: new Date() });
  }

  broadcastAnswer(interviewId: string, text: string) {
    this.logger.debug(`Broadcasting answer to interview:${interviewId}`);
    this.server
      .to(`interview:${interviewId}`)
      .emit('interview:answer', { text, timestamp: new Date() });
  }

  broadcastStatus(interviewId: string, status: string) {
    this.server
      .to(`interview:${interviewId}`)
      .emit('interview:status', { status, timestamp: new Date() });
  }

  broadcastTermination(interviewId: string, reason: string, message: string) {
    this.server.to(`interview:${interviewId}`).emit('interview:terminated', {
      interviewId,
      reason,
      message,
      timestamp: new Date(),
    });
  }
}

import {
  Controller,
  Post,
  Get,
  Param,
  UseGuards,
  Request,
  ForbiddenException,
} from '@nestjs/common';
import { CombinedAuthGuard } from '../auth/combined-auth.guard';
import { RecruiterControlService } from './services/recruiter-control.service';
import { InterviewAgentService } from './services/interview-agent.service';
import { LiveInterviewService } from './services/live-interview.service';

@Controller('interview-agent')
@UseGuards(CombinedAuthGuard)
export class InterviewAgentController {
  constructor(
    private readonly recruiterControlService: RecruiterControlService,
    private readonly interviewAgentService: InterviewAgentService,
    private readonly liveInterviewService: LiveInterviewService,
  ) {}

  @Post(':id/terminate')
  async terminateInterview(@Param('id') id: string, @Request() req) {
    // Enforce basic recruiter check. This assumes the JwtAuthGuard extracts user details
    const user = req.user;
    if (!user || user.role !== 'recruiter') {
      throw new ForbiddenException('Only recruiters can terminate interviews');
    }

    return await this.recruiterControlService.terminateInterview(id, user.id);
  }

  // A candidate might call this endpoint to submit an answer
  @Post(':id/answer')
  async processAnswer(@Param('id') id: string, @Request() req) {
    const user = req.user;
    // In a real system, you'd guarantee that the candidate issuing the answer is exactly the owner
    return await this.interviewAgentService.processAnswer(
      id,
      req.body.answer || '',
    );
  }

  @Get('active')
  async getActiveInterviews(@Request() req) {
    const user = req.user;
    console.log(
      `[InterviewAgentController] getActiveInterviews hit by user: ${user?.id || user?.sub} (${user?.role})`,
    );
    if (!user || user.role !== 'recruiter') {
      throw new ForbiddenException(
        `Only recruiters can view active interviews. Your current role is: ${user?.role || 'unknown'}`,
      );
    }
    const activeList = this.liveInterviewService.getActiveInterviews();
    console.log(
      `[InterviewAgentController] returning ${activeList.length} active interviews`,
    );
    return activeList;
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { GeminiService } from '../../gemini/gemini.service';
import { QuestionFallbackService } from './question-fallback.service';
import { InterviewSessionService } from './interview-session.service';

@Injectable()
export class InterviewAgentService {
  private readonly logger = new Logger(InterviewAgentService.name);

  constructor(
    private geminiService: GeminiService,
    private questionFallback: QuestionFallbackService,
    private sessionService: InterviewSessionService,
  ) {}

  private isSkipResponse(answer: string): boolean {
    if (!answer || answer.trim() === '') return false;

    const lowerAnswer = answer.toLowerCase().trim();
    const skipRegex =
      /\b(skip|i don't know|i do not know|no idea|pass|next question)\b/i;

    // A skip response is usually a short command, not a full paragraph that happens to contain a skip phrase.
    return skipRegex.test(lowerAnswer) && lowerAnswer.length < 40;
  }

  async processAnswer(id: string, answer: string): Promise<any> {
    const interview = await this.sessionService.getInterview(id);

    if (
      [
        'completed',
        'cancelled',
        'failed_interview',
        'terminated_by_recruiter',
      ].includes(interview.status)
    ) {
      throw new BadRequestException(
        `Cannot process answer. Interview is in status: ${interview.status}`,
      );
    }

    // Determine the last question asked (if any)
    const transcript = interview.transcript || [];
    const lastQuestion =
      transcript.length > 0 ? transcript[transcript.length - 1].question : null;

    // Skip detection logic
    if (this.isSkipResponse(answer)) {
      const { interview: updatedInterview, terminated } =
        await this.sessionService.incrementSkipCounter(id);
      if (terminated) {
        return {
          status: updatedInterview.status,
          message: 'Interview terminated due to multiple skipped questions.',
        };
      }
    }

    // Note: The candidate's answer was already appended to `interview.transcript`
    // by InterviewsService before calling this method.

    const nextQuestion = await this.generateNextQuestion(id, interview);
    await this.sessionService.logQuestion(id, nextQuestion);

    return {
      status: interview.status,
      question: nextQuestion,
    };
  }

  private async generateNextQuestion(
    id: string,
    interview: any,
  ): Promise<string> {
    const transcript = interview.transcript || [];
    const jobRole = interview.job?.title || 'Software Engineer';

    if (interview.status === 'ai_fallback_mode') {
      return await this.questionFallback.getNextFallbackQuestion(
        jobRole,
        interview.currentQuestionIndex,
      );
    }

    const history: {
      role: 'system' | 'user' | 'assistant';
      content: string;
    }[] = [
      {
        role: 'system',
        content: `You are an AI technical interviewer. Ask one question at a time.
Verify the candidate's last answer. Generate the next logical question to assess their technical knowledge, reasoning ability, and real project experience for a ${jobRole} role.
Do not reveal answers. Do not give hints. Do not ask multiple questions.`,
      },
    ];

    for (const entry of transcript) {
      if (entry.speaker === 'AI') {
        history.push({ role: 'assistant', content: entry.message });
      } else if (entry.speaker === 'Candidate') {
        history.push({ role: 'user', content: entry.message });
      } else {
        // Fallback for previous legacy transcript format
        if (entry.question) {
          history.push({ role: 'assistant', content: entry.question });
        }
        if (entry.answer) {
          history.push({ role: 'user', content: entry.answer });
        }
      }
    }

    const nextQuestion = await this.geminiService.generateNextQuestion(history);

    if (!nextQuestion) {
      this.logger.warn(
        `Failed to generate question via AI for ${id}. Switching to Fallback Mode.`,
      );
      await this.sessionService.activateFallbackMode(id);
      return await this.questionFallback.getNextFallbackQuestion(
        jobRole,
        interview.currentQuestionIndex,
      );
    }

    return nextQuestion;
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  Inject,
  forwardRef,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  Interview,
  InterviewStatus,
} from '../../interviews/entities/interview.entity';
import { LiveInterviewGateway } from '../gateways/live-interview.gateway';
import { InterviewsService } from '../../interviews/interviews.service';

@Injectable()
export class InterviewSessionService {
  private readonly logger = new Logger(InterviewSessionService.name);

  constructor(
    @InjectRepository(Interview)
    private interviewsRepository: Repository<Interview>,
    private liveInterviewGateway: LiveInterviewGateway,
    @Inject(forwardRef(() => InterviewsService))
    private interviewsService: InterviewsService,
  ) {}

  async getInterview(id: string): Promise<Interview> {
    const interview = await this.interviewsRepository.findOne({
      where: { id },
      relations: ['job', 'candidate', 'candidate.user'],
    });
    if (!interview) {
      throw new NotFoundException(`Interview with ID ${id} not found`);
    }
    return interview;
  }

  async addTranscriptEntry(
    id: string,
    question: string,
    answer: string,
  ): Promise<Interview> {
    const interview = await this.getInterview(id);
    const transcript = interview.transcript || [];

    transcript.push({
      question,
      answer,
      timestamp: new Date(),
    });

    interview.transcript = transcript;
    interview.currentQuestionIndex += 1;

    await this.interviewsRepository.save(interview);

    // Broadcast to recruiter if observing
    this.liveInterviewGateway.broadcastAnswer(id, answer);

    return interview;
  }

  async logQuestion(id: string, question: string): Promise<void> {
    // Broadcast question to recruiter
    this.liveInterviewGateway.broadcastQuestion(id, question);
  }

  async incrementSkipCounter(
    id: string,
  ): Promise<{ interview: Interview; terminated: boolean }> {
    const interview = await this.getInterview(id);
    interview.skipCounter = (interview.skipCounter || 0) + 1;

    const MAX_SKIPS = 2;
    let terminated = false;

    if (interview.skipCounter >= MAX_SKIPS) {
      this.logger.warn(
        `Interview ${id} skipped >= ${MAX_SKIPS} times. Auto-terminating.`,
      );
      terminated = true;

      // Notify candidate frontend
      this.liveInterviewGateway.broadcastTermination(
        id,
        'FAILED_INTERVIEW',
        'This interview has ended because multiple questions were skipped.',
      );

      await this.interviewsService.finishInterview(
        interview,
        'This interview has ended because multiple questions were skipped.',
        InterviewStatus.FAILED_INTERVIEW,
        'Candidate skipped multiple questions',
      );
    } else {
      await this.interviewsRepository.save(interview);
    }

    return { interview, terminated };
  }

  async activateFallbackMode(id: string): Promise<void> {
    const interview = await this.getInterview(id);
    if (interview.status !== InterviewStatus.AI_FALLBACK_MODE) {
      interview.status = InterviewStatus.AI_FALLBACK_MODE;
      await this.interviewsRepository.save(interview);
      this.liveInterviewGateway.broadcastStatus(
        id,
        InterviewStatus.AI_FALLBACK_MODE,
      );
      this.logger.log(`Interview ${id} switched to AI_FALLBACK_MODE`);
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import OpenAI from 'openai';

@Injectable()
export class OpenAiManagerService {
  private readonly logger = new Logger(OpenAiManagerService.name);
  private keys: string[] = [];
  private currentKeyIndex = 0;
  private openAiInstances: OpenAI[] = [];
  public isFallbackMode = false;

  constructor(private configService: ConfigService) {
    this.initializeKeys();
  }

  private initializeKeys() {
    const key1 =
      this.configService.get<string>('OPENAI_API_KEY') ||
      this.configService.get<string>('OPENAI_KEY_1');
    const key2 =
      this.configService.get<string>('OPENAI_API_KEY2') ||
      this.configService.get<string>('OPENAI_KEY_2');
    const key3 =
      this.configService.get<string>('OPENAI_API_KEY3') ||
      this.configService.get<string>('OPENAI_KEY_3');

    if (key1) this.keys.push(key1);
    if (key2) this.keys.push(key2);
    if (key3) this.keys.push(key3);

    if (this.keys.length === 0) {
      this.logger.warn(
        'No OPENAI API keys found! System will start in fallback mode.',
      );
      this.isFallbackMode = true;
    } else {
      this.keys.forEach((key) => {
        this.openAiInstances.push(new OpenAI({ apiKey: key }));
      });
    }
  }

  private get currentOpenAi(): OpenAI | null {
    if (this.isFallbackMode || this.openAiInstances.length === 0) {
      return null;
    }
    return this.openAiInstances[this.currentKeyIndex];
  }

  private rotateKey() {
    if (this.currentKeyIndex < this.keys.length - 1) {
      this.currentKeyIndex++;
      this.logger.log(`Switched to OpenAI API Key ${this.currentKeyIndex + 1}`);
    } else {
      this.logger.error(
        'All OpenAI API keys have been exhausted! Switching to AI_FALLBACK_MODE.',
      );
      this.isFallbackMode = true;
    }
  }

  async generateNextQuestion(
    history: { role: 'system' | 'user' | 'assistant'; content: string }[],
    retries = 0,
  ): Promise<string | null> {
    if (this.isFallbackMode) {
      return null; // Signals agent service to use fallback DB questions
    }

    const openAi = this.currentOpenAi;
    if (!openAi) return null;

    try {
      const response = await openAi.chat.completions.create({
        model: 'gpt-4o-mini', // Changed from gpt-4-turbo-preview to prevent 404 on low-tier keys
        messages: history,
        max_tokens: 150,
        temperature: 0.7,
      });

      return response.choices[0].message.content?.trim() || null;
    } catch (error: any) {
      this.logger.error(`OpenAI Error: ${error.message}`);

      // Handle rate limits or quota errors
      if (
        error?.status === 429 ||
        error?.code === 'insufficient_quota' ||
        error?.message?.includes('rate_limit_error') ||
        error?.message?.includes('quota_exceeded')
      ) {
        this.rotateKey();
        // Avoid infinite recursion, bound retries by key count
        if (retries < this.keys.length && !this.isFallbackMode) {
          return this.generateNextQuestion(history, retries + 1);
        }
      }

      // Other errors, or out of keys
      return null;
    }
  }

  async evaluateAnswer(question: string, answer: string): Promise<any | null> {
    if (this.isFallbackMode) return null;

    const openAi = this.currentOpenAi;
    if (!openAi) return null;

    try {
      const response = await openAi.chat.completions.create({
        model: 'gpt-4o-mini',
        messages: [
          {
            role: 'system',
            content:
              'You are an AI technical interviewer evaluating a candidate answer. Return a JSON with { "technicalScore": 1-10, "accuracyScore": 1-10, "communicationScore": 1-10, "confidenceScore": 1-10, "feedback": "Brief feedback" }',
          },
          { role: 'user', content: `Question: ${question}\nAnswer: ${answer}` },
        ],
        response_format: { type: 'json_object' },
      });

      return JSON.parse(response.choices[0].message.content || '{}');
    } catch (error: any) {
      this.logger.error(`OpenAI Evaluation Error: ${error.message}`);
      if (error?.status === 429 || error?.code === 'insufficient_quota') {
        this.rotateKey();
        if (!this.isFallbackMode) {
          return this.evaluateAnswer(question, answer); // basic retry
        }
      }
      return null;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  FallbackQuestion,
  FallbackQuestionCategory,
} from '../entities/fallback-question.entity';

@Injectable()
export class QuestionFallbackService {
  private readonly logger = new Logger(QuestionFallbackService.name);

  constructor(
    @InjectRepository(FallbackQuestion)
    private fallbackQuestionsRepo: Repository<FallbackQuestion>,
  ) {}

  async getNextFallbackQuestion(
    jobRole: string,
    currentQuestionIndex: number,
  ): Promise<string> {
    this.logger.log(
      `Fetching fallback question for ${jobRole} at index ${currentQuestionIndex}`,
    );

    // Find questions matching the role, ordered by their index
    let questions = await this.fallbackQuestionsRepo.find({
      where: { jobRole },
      order: { orderIndex: 'ASC' },
    });

    if (questions.length === 0) {
      // Check if there are generic fallback questions
      questions = await this.fallbackQuestionsRepo.find({
        order: { orderIndex: 'ASC' }, // Just get anything as a last resort
      });
    }

    let finalQuestions = questions.map((q) => q.question);

    const ABSOLUTE_FALLBACKS = [
      'Can you explain a complex project you worked on recently?',
      'What is the most challenging technical problem you have solved?',
      'Describe JAVA and how it is different from other languages?',
      'What is the difference between JAVA and JAVASCRIPT?',
      'What are your favorite programming languages or tools, and why?',
      'Describe a situation where you had to meet a tight deadline.',
      'How do you approach debugging a particularly tricky issue?',
      'What architecture patterns are you most familiar with?',
      'How do you stay updated with the latest trends in software development?',
      'Can you talk about a time when a project failed and what you learned from it?',
    ];

    // If there are no questions or very few, pad with absolute fallbacks to ensure variety
    if (finalQuestions.length < 5) {
      finalQuestions = [...finalQuestions, ...ABSOLUTE_FALLBACKS];
    }

    // Return the question at the current index, or loop back around
    return finalQuestions[currentQuestionIndex % finalQuestions.length];
  }
}

