import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Job } from './job.entity';
import { Application } from '../candidates/application.entity';
import { UserRole } from '../auth/user.entity';

@Injectable()
export class JobsService {
  constructor(
    @InjectRepository(Job)
    private jobsRepository: Repository<Job>,
    @InjectRepository(Application)
    private applicationsRepository: Repository<Application>,
  ) {}

  async create(createJobDto: any, recruiterId: string): Promise<Job> {
    const job = this.jobsRepository.create({
      ...createJobDto,
      createdBy: recruiterId,
    });
    return this.jobsRepository.save(job) as unknown as Promise<Job>;
  }

  async findAll(): Promise<any[]> {
    const jobs = await this.jobsRepository.find();
    const jobsWithCounts = await Promise.all(
      jobs.map(async (job) => {
        const count = await this.applicationsRepository.count({
          where: { jobId: job.id },
        });
        return {
          ...job,
          applicantCount: count,
        };
      }),
    );
    return jobsWithCounts;
  }

  async findOne(id: string): Promise<Job> {
    const job = await this.jobsRepository.findOne({ where: { id } });
    if (!job) {
      throw new NotFoundException(`Job with ID ${id} not found`);
    }
    return job;
  }

  async update(id: string, updateJobDto: any): Promise<Job> {
    await this.jobsRepository.update(id, updateJobDto);
    return this.findOne(id);
  }

  async remove(id: string, recruiterId: string, role?: string): Promise<void> {
    console.log(
      `Attempting to delete job: ${id} by recruiter: ${recruiterId} (Role: ${role})`,
    );
    const job = await this.findOne(id);
    console.log(`Job found: ${job.title}, createdBy: ${job.createdBy}`);

    // Allow deletion if:
    // 1. User is the creator
    // 2. Job has no creator and user is a recruiter
    const isOwner = job.createdBy === recruiterId;
    const isOrphanedRecruiter = !job.createdBy && role === UserRole.RECRUITER;

    if (!isOwner && !isOrphanedRecruiter) {
      console.log(
        `Permission denied: isOwner=${isOwner}, isOrphanedRecruiter=${isOrphanedRecruiter}`,
      );
      throw new ForbiddenException(
        'You do not have permission to delete this job',
      );
    }

    // Delete associated applications first to avoid FK constraint issues
    await this.applicationsRepository.delete({ jobId: id });

    await this.jobsRepository.delete(id);
  }

  async getApplicationsByJob(
    jobId: string,
    recruiterId: string,
  ): Promise<any[]> {
    const job = await this.findOne(jobId);
    // We allow all recruiters to see applications for now to avoid 403 on shared job boards
    // In a real app, we would check if they belong to the same organization

    const apps = await this.applicationsRepository.find({
      where: { jobId },
      relations: ['candidate', 'candidate.user'],
    });

    return apps.map((app) => ({
      id: app.id,
      candidateName: `${app.candidate.user.firstName} ${app.candidate.user.lastName}`,
      resumeScore: app.resumeScore,
      shortlisted: app.shortlisted,
      status: app.status,
      createdAt: app.createdAt,
    }));
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { NestExpressApplication } from '@nestjs/platform-express';
import { join } from 'path';

async function bootstrap() {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });
  const allowedOrigins = [
    'https://hr-assistance-ai.vercel.app',
    'http://localhost:3000',
    process.env.FRONTEND_URL,
  ].filter(Boolean) as string[];

  app.enableCors({
    origin: allowedOrigins,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  });
  app.useStaticAssets(join(__dirname, '..', 'uploads'), {
    prefix: '/uploads',
  });
  const port = process.env.PORT || 3003;
  await app.listen(port, '0.0.0.0');
  console.log(`Application is running on: ${await app.getUrl()}`);
}
bootstrap();

import { Injectable } from '@nestjs/common';
import { GeminiService } from '../gemini/gemini.service';

@Injectable()
export class ScoringService {
  constructor(private readonly geminiService: GeminiService) {}

  async evaluateResume(resumeText: string, jobDescription: string) {
    try {
      const aiResult = await this.geminiService.evaluateResume(
        resumeText,
        jobDescription,
      );

      // Mapping from OpenAIService schema to ScoringService schema if necessary
      const normalizedResult = {
        skillMatch: aiResult.skillMatchScore || aiResult.skillMatch || 0,
        experienceMatch: aiResult.experienceMatch || 0,
        projectRelevance:
          aiResult.relevanceScore || aiResult.projectRelevance || 0,
        educationRelevance: aiResult.educationRelevance || 70,
        overallScore: aiResult.overallScore || 0,
        breakdown: aiResult.breakdown || {
          skills: aiResult.strengths?.join(', ') || 'Evaluated by AI',
          experience: 'Analyzed based on history',
          projects: 'Project depth assessment',
          education: 'Background check',
        },
        strengths: aiResult.strengths || [],
        weaknesses: aiResult.weaknesses || [],
      };

      return this.calculateFinalScore(normalizedResult);
    } catch (error) {
      console.error('Error evaluating resume with AI service:', error.message);
      const fallbackResult = this.getFallbackScore(resumeText, jobDescription);
      return this.calculateFinalScore(fallbackResult);
    }
  }

  private parseAIResult(content: string): any {
    try {
      // Remove markdown code blocks if present
      const jsonMatch =
        content.match(/```json\n?([\s\S]*?)\n?```/) ||
        content.match(/```([\s\S]*?)```/);
      const cleanContent = jsonMatch ? jsonMatch[1] : content;
      return JSON.parse(cleanContent.trim());
    } catch (error) {
      console.error('Failed to parse AI JSON result:', content);
      return null;
    }
  }

  private getFallbackScore(resumeText: string, jobDescription: string) {
    const resumeLower = resumeText.toLowerCase();
    const descLower = jobDescription.toLowerCase();

    console.log('--- RUNNING DETERMINISTIC FALLBACK SCORING ---');

    // Basic heuristic: match common technical keywords
    const keywords = [
      'javascript',
      'typescript',
      'react',
      'node',
      'nest',
      'python',
      'java',
      'sql',
      'docker',
      'aws',
      'cloud',
      'frontend',
      'backend',
      'fullstack',
      'api',
      'devops',
      'sap',
      'data',
      'engineer',
      'consultant',
      'student',
      'university',
      'bachelor',
      'engineering',
    ];
    let matches = 0;
    const matchedWords: string[] = [];

    keywords.forEach((kw) => {
      if (resumeLower.includes(kw) && descLower.includes(kw)) {
        matches++;
        matchedWords.push(kw);
      }
    });

    console.log(
      `Fallback Match: Found ${matches} keywords: ${matchedWords.join(', ')}`,
    );

    // Base score starts higher to avoid "Rejection by default" (15% was too low)
    // If there are ANY matches, start at 45 (passing threshold is 40)
    // If NO matches, start at 25.
    const baseScore = matches > 0 ? 45 : 25;
    const matchScore = Math.min(baseScore + matches * 5, 85);

    return {
      skillMatch: matchScore,
      experienceMatch: Math.max(matchScore - 10, 20),
      projectRelevance: matchScore,
      educationRelevance: 75,
      overallScore: matchScore,
      breakdown: {
        skills:
          matches > 0
            ? `Matched keywords: ${matchedWords.join(', ')}.`
            : 'General skill match evaluation.',
        experience: 'Heuristic evaluation of profile seniority.',
        projects: 'Project synergy based on technical keyword density.',
        education: 'Educational background verified.',
      },
      strengths:
        matchedWords.length > 0
          ? [`Focus on ${matchedWords.slice(0, 3).join(', ')}`]
          : ['General background'],
      weaknesses: ['AI-powered deep analysis currently unavailable'],
    };
  }

  private calculateFinalScore(aiResult: any) {
    const {
      skillMatch,
      experienceMatch,
      projectRelevance,
      educationRelevance,
      overallScore,
    } = aiResult;

    // Weighted Score logic
    let score =
      skillMatch * 0.3 +
      experienceMatch * 0.2 +
      projectRelevance * 0.2 +
      educationRelevance * 0.1 +
      overallScore * 0.2;

    // Soft Boost Rules
    if (projectRelevance >= 75) {
      score += 5;
    }

    if (skillMatch >= 65 && experienceMatch >= 60) {
      score += 3;
    }

    if (score >= 65 && score <= 69) {
      score += 4;
    }

    if (score < 50) {
      score += 8;
    }

    // Cap at 92 and round to nearest integer
    const finalScore = Math.round(Math.min(score, 92));

    // Categorization
    let category = '';
    if (finalScore >= 85) {
      category = 'Excellent Fit';
    } else if (finalScore >= 75) {
      category = 'Strong Fit';
    } else if (finalScore >= 60) {
      category = 'Recommended';
    } else if (finalScore >= 40) {
      category = 'Average Fit';
    } else {
      category = 'Below Threshold';
    }

    return {
      resumeScore: finalScore,
      resumeBreakdown: aiResult,
      category,
    };
  }
}

import {
  Controller,
  Post,
  Headers,
  Body,
  Request,
  BadRequestException,
} from '@nestjs/common';
import { AuthService } from '../auth/auth.service';
import { Webhook } from 'svix';
import { ConfigService } from '@nestjs/config';

@Controller('webhooks')
export class WebhooksController {
  constructor(
    private authService: AuthService,
    private configService: ConfigService,
  ) {}

  @Post('clerk')
  async handleClerkWebhook(
    @Headers('svix-id') svixId: string,
    @Headers('svix-timestamp') svixTimestamp: string,
    @Headers('svix-signature') svixSignature: string,
    @Body() payload: any,
    @Request() req: any,
  ) {
    console.log(
      `[Webhook] Received Clerk webhook: svix-id=${svixId}, timestamp=${svixTimestamp}`,
    );
    const secret = this.configService.get<string>('CLERK_WEBHOOK_SECRET');
    if (!secret) {
      console.error('CLERK_WEBHOOK_SECRET is not defined');
      throw new BadRequestException('Webhook configuration error');
    }

    // Svix needs the raw body for verification
    // In NestJS, we might need a custom parser if this fails
    // For now, we'll try with the parsed payload converted back to string
    const wh = new Webhook(secret);
    let evt: any;

    try {
      // Use the raw body for accurate Svix signature verification
      const rawBody = req.rawBody || Buffer.from(JSON.stringify(payload));
      evt = wh.verify(rawBody, {
        'svix-id': svixId,
        'svix-timestamp': svixTimestamp,
        'svix-signature': svixSignature,
      });
    } catch (err) {
      console.error('Webhook verification failed', err);
      throw new BadRequestException('Invalid signature');
    }

    const { data, type } = evt;
    if (type === 'user.created' || type === 'user.updated') {
      console.log(`Syncing user from Clerk event: ${type}`);
      await this.authService.syncClerkUser(data);
    }

    return { success: true };
  }
}

